python -X utf8 -c "
import gzip,json,re
L=gzip.open('data/b671_narrow_run2_points.jsonl.gz','rt',encoding='utf-8').read().split('\n')
pts={}
for l in L:
    if not l.strip(): continue
    r=json.loads(l)
    if r.get('kind')=='OFF': pts[r['idx']]=(r['reading'],r['depth'],r['seconds'])
t3=open('data/b671_narrow_run3.txt',encoding='utf-8').read()
r3={int(m.group(1)):int(m.group(2)) for m in re.finditer(r'OFF (\d+) : NARROWED at depth 40 ; (\d+) s',t3)}
tot=0;rows=[]
for i in sorted(pts):
    rd,dp,s=pts[i]
    if i in r3: spd=r3[i]/37.0; src='run3 %d s / 37 depths'%r3[i]
    else: spd=s/float(dp); src='run2 %d s / %d depths'%(s,dp)
    rows.append((i,rd,round(spd),src)); tot+=20*spd
for r in rows: print(r)
print('n',len(rows),'price 20 halvings CPU s',round(tot), 'hours',round(tot/3600,1))
"
